import { getFirstItemByPropertyValue } from '../../../../core/utils/_arrayutils';
import { createDeferred } from '../../../../core/utils/_createDeferred';
import { getLocalization } from '../../../../property-grid/localization/_localization';
import { MongoDBDataConnection } from '../../../dataSource/mongoDB/mongoDBDataConnection';
import { ChooseAvailableItemPage } from '../../chooseAvailablePage';
import { MongoDBDataSourceWizardPageId } from '../../pageId';
export class ChooseMongoDBDataConnectionPage extends ChooseAvailableItemPage {
    commit() {
        const selectedItem = this.selectedItems()[0].name;
        const connection = this._connection.name() === selectedItem ? this._connection
            : new MongoDBDataConnection();
        connection.name(selectedItem);
        return createDeferred().resolve({
            connectionJson: connection.serialize(),
        }).promise();
    }
    initialize(state) {
        this._connection = MongoDBDataConnection.from(state.connectionJson);
        return super.initialize(state);
    }
    _getSelectedItem(state) {
        return getFirstItemByPropertyValue(this.items(), 'name', this._connection.name()) || super._getSelectedItem();
    }
}
export function _registerChooseMongoDBDataConnectionPage(factory, wizardOptions) {
    factory.registerMetadata(MongoDBDataSourceWizardPageId.ChooseMongoDBDataConnectionPage, {
        create: () => {
            return new ChooseMongoDBDataConnectionPage(wizardOptions.connectionStrings?.mongodb, false, wizardOptions.getMongoDBConnectionStrings);
        },
        description: getLocalization('Choose a data connection.', 'AnalyticsCoreStringId.SqlDSWizard_PageChooseConnection'),
        getState: (state) => state.mongoDBDataSourceWizard,
        setState: (data, state) => {
            state.connectionJson = data.connectionJson;
        },
        resetState: (state, defaultState) => {
            state.connectionJson = defaultState.connectionJson;
        },
        template: 'dxrd-page-selectitems'
    });
}
